pub(crate) fn strip_frontmatter(text: &str) -> &str {
    // 先剥 UTF-8 BOM，否则 frontmatter 探测整体失效
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    if !text.starts_with("---") {
        return text;
    }
    let body = &text[3..];
    match body.find("\n---") {
        Some(end) => body[end + 4..].trim_start_matches('\n'),
        None => text,
    }
}

